#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/vscode/tasks/setup-vscode.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Reconcile this repo's editor profile with its recommended extensions"
# `dir` is load-bearing here and not decoration: the message below tells a human
# to run `code --profile <name> .`, and the folder that `.` names is what the
# editor associates the profile with. Run from a subdirectory, the association
# would be for the wrong folder.
# MISE dir="{{ config_root }}"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}

import locale
import os
import re
import shutil
import subprocess
import sys
import time

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

# The extensions half of the editor setup: `.vscode/extensions.json` is the list
# the repo composed from its packs, and this makes a profile match it — install
# what is listed and missing, REMOVE what is installed and no longer listed.
#
# **A per-repo profile, not a global install.** A recommendation list only ever
# prompts; accepting one installs globally, so a repo you worked on for a week
# leaves its whole toolchain enabled in every other window forever. A profile is
# the editor's own answer to that, and it is the only one that makes "stale
# extension" a thing this task can act on: pruning globally would uninstall a
# neighbouring repo's tools.
#
# **The profile name is `$REPO_NAME`** — the slug in `.config/mise.toml`'s
# `[env]`, the same token the `p:<id>:*` task group carries. Reading it rather
# than deriving one is what keeps the profile stable inside a linked worktree,
# whose directory is named after the branch.
#
# **Everything here is best-effort and silent when it does not apply.** It runs
# from `setup`, which a machine without the editor must still finish.

EDITOR_CLI = "code"
RECOMMENDATIONS = f"{os.environ['MISE_PROJECT_ROOT']}/.vscode/extensions.json"


def sort_unique(items):
  """The items without duplicates, sorted in the collation order of the locale,
  as `sort -u` gives them."""
  try:
    locale.setlocale(locale.LC_COLLATE, "")
  except locale.Error:
    pass
  return sorted(set(items), key=locale.strxfrm)


def read_recommendations():
  """The ids of the `recommendations` array of the JSONC file.

  The file is JSONC: comments are legal and the shipped one has them. Rather
  than pull in a parser, read the one array this task cares about line by line
  — strip `//` and `/* */`, then collect the quoted strings between
  `"recommendations"` and its closing bracket. `unwantedRecommendations` sits in
  the same file and is deliberately not collected.
  """
  ids = []
  in_block = False
  collecting = False
  with open(RECOMMENDATIONS, encoding="utf-8", errors="surrogateescape") as f:
    lines = f.read().split("\n")
  if lines and lines[-1] == "":
    lines.pop()
  for line in lines:
    # Comments first, in both spellings. A block comment spanning lines is
    # carried on the in_block flag; a line comment runs to end of line. An
    # extension id contains neither sequence, so no id can be eaten by this.
    line = re.sub(r"/\*[^*]*\*/", "", line)
    if in_block:
      if "*/" not in line:
        continue
      line = re.sub(r"^.*\*/", "", line, count=1)
      in_block = False
    if "/*" in line:
      line = re.sub(r"/\*.*$", "", line, count=1)
      in_block = True
    line = re.sub(r"//.*$", "", line, count=1)

    # Then the one array this task reads. `unwantedRecommendations` sits in the
    # same file and is deliberately not collected: it is what the editor should
    # stop suggesting, not what this profile should hold.
    if '"recommendations"' in line:
      collecting = True
      line = re.sub(r'^.*"recommendations"[^[]*\[', "", line, count=1)
    if collecting:
      body = line
      if "]" in body:
        body = re.sub(r"\].*$", "", body, count=1)
        collecting = False
      chunks = body.split('"')
      ids += [chunk for chunk in chunks[1::2] if chunk]
  return sort_unique(ids)


def probe_profile(repo_name):
  """The extensions of the profile, or None when the profile is missing.

  The two streams are kept apart rather than merged: stdout is the id list, and
  stderr carries both the sentinel and whatever runtime deprecation notices the
  editor's bundled node feels like printing that release. Merging them would
  put those notices in the list and try to uninstall one.
  """
  result = subprocess.run(
    [EDITOR_CLI, "--profile", repo_name, "--list-extensions"],
    capture_output=True,
    text=True,
    errors="surrogateescape",
    check=False,
  )
  if f"Profile '{repo_name}' not found." in result.stderr:
    return None
  return result.stdout.rstrip("\n")


def editor(repo_name, *args):
  """Whether `code --profile <repo_name> <args>` succeeds, with its output
  discarded."""
  result = subprocess.run(
    [EDITOR_CLI, "--profile", repo_name, *args],
    stdout=subprocess.DEVNULL,
    stderr=subprocess.DEVNULL,
    check=False,
  )
  return result.returncode == 0


def main():
  if shutil.which(EDITOR_CLI) is None:
    return 0

  # Without a recommendation list there is nothing to reconcile.
  if not os.path.isfile(RECOMMENDATIONS):
    return 0

  repo_name = os.environ.get("REPO_NAME", "")
  helpers.print_header(f"Reconciling the {repo_name} editor profile ...")

  if not repo_name or repo_name == "unfilled":
    helpers.print_warn("REPO_NAME is not set — skipping the editor profile.")
    helpers.print_yellow("Set repo_name in .config/bootstrap/repo.toml, then run setup:configs.")
    return 0

  wanted = read_recommendations()

  # **A profile the editor has never created cannot be written to from here.**
  # Measured on VS Code 1.136.1: `--profile <name>` combines with
  # `--list-extensions`, `--install-extension` and `--uninstall-extension`, but
  # only once the profile EXISTS — and none of those three creates it. On a
  # missing profile the CLI writes `Profile '<name>' not found.` to STDERR and,
  # for `--list-extensions`, still exits 0 — so neither the status nor stdout
  # says anything, and that one line is the whole signal. Creating a profile is
  # a windowed action: a window opened under it creates the profile. Opening the
  # folder under it also records the association, but only when no window has
  # the folder open: else the editor only focuses that window, and creates
  # nothing. So a missing profile is created by a new empty window under it,
  # and the task waits for the editor to report it before it installs the list.
  # The `code` alias of this tool then opens the folder under the profile.
  before = probe_profile(repo_name)
  if before is None:
    helpers.print_subheader(f"Creating the '{repo_name}' editor profile ...")
    helpers.print_info("Opening a new empty window with the profile.")
    opened = subprocess.run(
      [EDITOR_CLI, "--new-window", "--profile", repo_name],
      stdout=subprocess.DEVNULL,
      stderr=subprocess.DEVNULL,
      check=False,
    )
    if opened.returncode != 0:
      helpers.print_warn("The editor did not open - skipping the editor profile.")
      return 0
    # The editor creates the profile after the CLI returns.
    waited = 0
    before = probe_profile(repo_name)
    while before is None:
      if waited >= 30:
        helpers.print_warn(f"The '{repo_name}' editor profile does not exist after 30 seconds.")
        helpers.print_yellow("Run this task again when the editor window is open.")
        return 0
      time.sleep(1)
      waited += 1
      before = probe_profile(repo_name)
    helpers.print_success(f"Profile '{repo_name}' created.")
    # A new profile copies nothing from the Default profile. This repo's own
    # settings live in .vscode/settings.json; the user ones stay in Default.
    helpers.print_yellow("Close the empty window. Then close each window of this folder, and")
    helpers.print_yellow("run `code` here: the folder then opens under the profile, always.")
    helpers.print_yellow("To use your user settings and keybindings in the profile, turn on")
    helpers.print_yellow("'Use Default profile' for them in its profile editor.")

  installed = sort_unique(line for line in before.split("\n") if not re.fullmatch(r"\s*", line))
  installed_set = set(installed)
  wanted_set = set(wanted)

  to_install = [i for i in wanted if i not in installed_set]
  to_remove = [i for i in installed if i not in wanted_set]

  if not to_install and not to_remove:
    helpers.print_success(f"Profile '{repo_name}' already matches .vscode/extensions.json.")
    return 0

  if to_install:
    helpers.print_subheader("Installing ...")
    for extension in to_install:
      helpers.print_wait(f"  {extension} ... ")
      if editor(repo_name, "--install-extension", extension):
        helpers.print_success()
      else:
        # A id that no longer exists in the marketplace is a stale list, not a
        # broken machine: name it and keep going, so one dead entry does not
        # stop the rest of the toolchain from arriving.
        helpers.print_warn("FAILED (not installed)")

  # **Pruning is the half a recommendation list cannot do.** An extension
  # dropped from the list stays installed forever otherwise, and the profile
  # drifts into exactly the global-install pile it was created to avoid. Scoped
  # to this profile, so nothing another repo relies on is touched.
  if to_remove:
    helpers.print_subheader("Removing (installed here, no longer recommended) ...")
    for extension in to_remove:
      helpers.print_wait(f"  {extension} ... ")
      if editor(repo_name, "--uninstall-extension", extension):
        helpers.print_success()
      else:
        helpers.print_warn("FAILED (still installed)")

  helpers.print_success(f"Profile '{repo_name}' reconciled.")
  return 0


if __name__ == "__main__":
  sys.exit(main())
